# Secure sensitive-data vault.
# Requires: pip install cryptography

import base64
import getpass
import json
import os
import sys
import tempfile
import uuid
import hashlib
from datetime import datetime, timezone

from cryptography.fernet import Fernet, InvalidToken

ITERATIONS = 600000
SALT_SIZE = 16
DEFAULT_VAULT_PATH = os.path.join(os.path.expanduser("~"), ".secure_vault.json")

CATEGORY_FIELDS = {
    "card": ["cardholder", "card_number", "expiry", "cvv"],
    "personal": ["full_name", "date_of_birth", "ssn", "address", "phone", "email"],
}
SENSITIVE_FIELDS = {"card_number", "cvv", "ssn", "date_of_birth"}


def derive_key(password, salt):
    raw = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, ITERATIONS, dklen=32)
    return base64.urlsafe_b64encode(raw)


def encrypt_records(key, records):
    return Fernet(key).encrypt(json.dumps(records).encode("utf-8"))


def decrypt_records(key, token):
    return json.loads(Fernet(key).decrypt(token).decode("utf-8"))


def save_vault(path, salt, key, records):
    payload = {
        "version": 1,
        "salt": base64.b64encode(salt).decode("ascii"),
        "data": encrypt_records(key, records).decode("ascii"),
    }
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".vault_", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(payload, fh)
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, path)
    except Exception:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise


def open_vault(path, password):
    if not os.path.exists(path):
        salt = os.urandom(SALT_SIZE)
        key = derive_key(password, salt)
        records = []
        save_vault(path, salt, key, records)
        return key, salt, records

    with open(path, "r", encoding="utf-8") as fh:
        payload = json.load(fh)
    salt = base64.b64decode(payload["salt"])
    key = derive_key(password, salt)
    try:
        records = decrypt_records(key, payload["data"].encode("ascii"))
    except (InvalidToken, ValueError):
        raise ValueError("Wrong master password or corrupted vault.")
    return key, salt, records


def luhn_valid(number):
    digits = number.replace(" ", "").replace("-", "")
    if not digits.isdigit() or not (12 <= len(digits) <= 19):
        return False
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


def mask_value(value, keep=4):
    value = str(value)
    if len(value) <= keep:
        return "*" * len(value)
    return "*" * (len(value) - keep) + value[-keep:]


def add_entry(records, category, label, data):
    if category not in CATEGORY_FIELDS:
        raise ValueError("Unknown category: " + category)
    for field in CATEGORY_FIELDS[category]:
        if not str(data.get(field, "")).strip():
            raise ValueError("Missing required field: " + field)
    if category == "card" and not luhn_valid(data["card_number"]):
        raise ValueError("Invalid card number (failed Luhn check).")
    entry = {
        "id": uuid.uuid4().hex,
        "category": category,
        "label": label,
        "created": datetime.now(timezone.utc).isoformat(),
        "data": {k: str(data[k]).strip() for k in CATEGORY_FIELDS[category]},
    }
    records.append(entry)
    return entry


def list_entries(records):
    summaries = []
    for e in records:
        summaries.append({
            "id": e["id"],
            "category": e["category"],
            "label": e["label"],
            "created": e["created"],
        })
    return summaries


def get_entry(records, entry_id):
    for e in records:
        if e["id"] == entry_id:
            return e
    return None


def masked_entry(entry):
    result = {}
    for k, v in entry["data"].items():
        if k in SENSITIVE_FIELDS:
            result[k] = mask_value(v)
        else:
            result[k] = v
    return result


def delete_entry(records, entry_id):
    for i, e in enumerate(records):
        if e["id"] == entry_id:
            del records[i]
            return True
    return False


def prompt_fields(category):
    data = {}
    for field in CATEGORY_FIELDS[category]:
        if field in SENSITIVE_FIELDS:
            data[field] = getpass.getpass(f"  {field}: ")
        else:
            data[field] = input(f"  {field}: ")
    return data


def print_menu():
    print("\n=== Secure Vault ===")
    print("1) List entries")
    print("2) View entry (sensitive fields masked)")
    print("3) Add card")
    print("4) Add personal info")
    print("5) Delete entry")
    print("6) Quit")


def run_cli(path):
    password = getpass.getpass("Master password: ")
    if not password:
        print("Master password cannot be empty.")
        return 1
    try:
        key, salt, records = open_vault(path, password)
    except ValueError as exc:
        print(exc)
        return 1

    while True:
        print_menu()
        choice = input("Select: ").strip()
        try:
            if choice == "1":
                items = list_entries(records)
                if not items:
                    print("No entries.")
                for it in items:
                    print(f"[{it['id']}] {it['category']:9} {it['label']}  (created {it['created']})")

            elif choice == "2":
                entry_id = input("Entry id: ").strip()
                entry = get_entry(records, entry_id)
                if not entry:
                    print("Not found.")
                else:
                    print(json.dumps(masked_entry(entry), indent=2))

            elif choice == "3":
                label = input("Label: ").strip() or "card"
                data = prompt_fields("card")
                add_entry(records, "card", label, data)
                save_vault(path, salt, key, records)
                print("Card stored.")

            elif choice == "4":
                label = input("Label: ").strip() or "personal"
                data = prompt_fields("personal")
                add_entry(records, "personal", label, data)
                save_vault(path, salt, key, records)
                print("Personal info stored.")

            elif choice == "5":
                entry_id = input("Entry id to delete: ").strip()
                if delete_entry(records, entry_id):
                    save_vault(path, salt, key, records)
                    print("Deleted.")
                else:
                    print("Not found.")

            elif choice == "6":
                save_vault(path, salt, key, records)
                print("Vault locked.")
                return 0

            else:
                print("Invalid selection.")
        except (ValueError, KeyError) as exc:
            print("Error:", exc)


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_VAULT_PATH
    try:
        return run_cli(path)
    except (KeyboardInterrupt, EOFError):
        print("\nExiting.")
        return 130


if __name__
